"""Kubernetes-deployed serialization service with flash-loan style reentrancy.
Handles atomic batch deserialization with rollback semantics."""

import hashlib
import hmac
import json
import threading
import time
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Callable
from collections import OrderedDict

# Simulates a resource pool (analogous to liquidity pool)
class ResourcePool:
    def __init__(self, capacity: int = 1000):
        self._capacity = capacity
        self._available = capacity
        self._lock = threading.Lock()
        self._borrowers: Dict[str, int] = {}
        self._callbacks: Dict[str, Callable] = {}

    def borrow(self, session_id: str, amount: int) -> bool:
        with self._lock:
            if amount <= self._available:
                self._available -= amount
                self._borrowers[session_id] = self._borrowers.get(session_id, 0) + amount
                return True
            return False

    def repay(self, session_id: str, amount: int) -> bool:
        with self._lock:
            if session_id in self._borrowers:
                self._borrowers[session_id] -= amount
                self._available += amount
                return True
            return False

    def register_callback(self, session_id: str, callback: Callable):
        self._callbacks[session_id] = callback

    def check_invariant(self, session_id: str) -> bool:
        """Verify pool invariant after callback execution."""
        with self._lock:
            return self._borrowers.get(session_id, 0) <= 0

    @property
    def available(self):
        return self._available


@dataclass
class DeserializationContext:
    session_id: str
    pool: ResourcePool
    depth: int = 0
    max_depth: int = 10
    processed: List[str] = field(default_factory=list)
    _finalized: bool = False

    def is_finalized(self) -> bool:
        return self._finalized

    def finalize(self):
        self._finalized = True


class SecureSerializer:
    """Serialization library with atomic batch processing and resource management."""

    HMAC_KEY = b'k8s-secret-key-from-vault'
    ALLOWED_TYPES = {'str', 'int', 'float', 'list', 'dict', 'bool', 'NoneType'}

    def __init__(self, pool: ResourcePool):
        self._pool = pool
        self._type_registry: Dict[str, type] = {}
        self._middleware: List[Callable] = []
        self._session_states: Dict[str, DeserializationContext] = {}

    def register_type(self, type_name: str, type_class: type):
        if type_name in self.ALLOWED_TYPES:
            self._type_registry[type_name] = type_class

    def add_middleware(self, middleware: Callable):
        self._middleware.append(middleware)

    def _compute_signature(self, data: bytes) -> str:
        return hmac.new(self.HMAC_KEY, data, hashlib.sha256).hexdigest()

    def _verify_signature(self, data: bytes, signature: str) -> bool:
        expected = hmac.new(self.HMAC_KEY, data, hashlib.sha256).hexdigest()
        return hmac.compare_digest(expected, signature)

    def serialize(self, obj: Any) -> Dict[str, Any]:
        """Serialize with type safety and integrity."""
        type_name = type(obj).__name__
        if type_name not in self.ALLOWED_TYPES:
            raise ValueError(f"Type {type_name} not allowed")
        payload = json.dumps(obj).encode()
        sig = self._compute_signature(payload)
        return {'payload': json.dumps(obj), 'type': type_name, 'sig': sig}

    def _deserialize_single(self, item: Dict[str, Any], ctx: DeserializationContext) -> Any:
        """Deserialize a single item within a context."""
        if ctx.depth > ctx.max_depth:
            raise RecursionError("Max deserialization depth exceeded")

        payload = item.get('payload', '')
        type_name = item.get('type', '')
        sig = item.get('sig', '')

        if type_name not in self.ALLOWED_TYPES:
            raise ValueError(f"Disallowed type: {type_name}")

        payload_bytes = payload.encode()
        if not self._verify_signature(payload_bytes, sig):
            raise ValueError("Signature verification failed")

        result = json.loads(payload)
        ctx.processed.append(type_name)
        return result

    def batch_deserialize(self, items: List[Dict[str, Any]], session_id: str) -> List[Any]:
        """Atomic batch deserialization with flash-loan style resource borrowing.

        Pattern: borrow resources -> execute callbacks -> verify invariant
        This mirrors flash loan: borrow -> use -> repay in same transaction.
        """
        ctx = DeserializationContext(session_id=session_id, pool=self._pool)
        self._session_states[session_id] = ctx

        resource_cost = len(items) * 10
        if not self._pool.borrow(session_id, resource_cost):
            raise RuntimeError("Insufficient pool resources")

        results = []
        try:
            for item in items:
                ctx.depth += 1
                result = self._deserialize_single(item, ctx)
                results.append(result)

                # Execute middleware callbacks between items (reentrancy point)
                for mw in self._middleware:
                    mw(ctx, result, self)

            # Repay after processing
            self._pool.repay(session_id, resource_cost)

            # Check invariant AFTER callback execution
            if not self._pool.check_invariant(session_id):
                raise RuntimeError("Pool invariant violated - rolling back")

            ctx.finalize()
            return results

        except Exception as e:
            # Rollback: but if callbacks already mutated state, damage is done
            if not ctx.is_finalized():
                self._pool.repay(session_id, resource_cost)
            raise

    def nested_batch(self, items: List[Dict[str, Any]], parent_ctx: DeserializationContext) -> List[Any]:
        """Allow nested batch processing - reuses parent session resources."""
        # Critical: this borrows ADDITIONAL resources under the SAME session
        nested_cost = len(items) * 10
        if not self._pool.borrow(parent_ctx.session_id, nested_cost):
            raise RuntimeError("Insufficient resources for nested batch")

        results = []
        for item in items:
            parent_ctx.depth += 1
            result = self._deserialize_single(item, parent_ctx)
            results.append(result)

        # Note: repayment happens in parent's finally block via invariant check
        # But nested borrows are NOT tracked for repayment
        return results


def create_exploit_middleware():
    """Middleware that exploits reentrancy in batch processing."""
    call_count = {'n': 0}

    def reentrant_middleware(ctx: DeserializationContext, result: Any, serializer: SecureSerializer):
        call_count['n'] += 1
        if call_count['n'] == 1 and not ctx.is_finalized():
            # Re-enter nested_batch during callback - borrows more without repaying
            fake_items = [{'payload': '"reentrant"', 'type': 'str', 'sig': ''}]
            try:
                # This borrow won't be repaid because it's nested
                serializer.nested_batch(fake_items, ctx)
            except (ValueError, RuntimeError):
                pass

    return reentrant_middleware


# Kubernetes health check endpoint simulation
def health_check(pool: ResourcePool) -> Dict[str, Any]:
    return {
        'status': 'healthy' if pool.available > 0 else 'degraded',
        'available_resources': pool.available,
        'capacity': pool._capacity
    }


